SELECT wc.id
FROM work_cases wc
WHERE wc.worker_id = #{workerId}
  AND wc.workplace_id = #{workplaceId}
  AND wc.status = 'COMPLETED'
  AND wc.starts_at <= #{readyAt}
  AND wc.ends_at > #{checkoutAfter}
ORDER BY wc.starts_at, wc.id

SELECT EXISTS(
    SELECT 1
    FROM attendance_records
    WHERE work_case_id = #{workCaseId}
      AND attendance_type = #{attendanceType}
      AND result = 'SUCCESS'
)

mapper.update:
UPDATE work_cases
SET status = #{status}
WHERE id = #{workCaseId}
  AND status = #{expectedStatus}
